use imu_joint_bridge::protocol::Server;
use serde_json::{json,Value};
fn setup()->Server{let mut s=Server::default();s.native(json!({"kind":"native_clock_req","sid":"native-session","seq":0,"nonce":"a","n1_ns":1000000000u64}),1792923000000000,1792923000000010).unwrap();s.watch(json!({"p":"J_HELLO1","sid":"watch-session","w1_ms":1792923000000u64,"duration_ms":60000}),1792923000000000,1792923000000010).unwrap();s}
fn req()->Value{json!({"p":"J_CLK_REQ1","sid":"watch-session","native_sid":"native-session","seq":0,"w1_ms":1792923000000u64})}
fn drop()->Value{json!({"p":"J_CLK_DROP1","sid":"watch-session","native_sid":"native-session","seq":0,"w1_ms":1792923000000u64,"reason":"reply_too_late"})}
#[test]fn acknowledged_discard_closes_pending_without_a_valid_observation(){let mut s=setup();s.watch(req(),1792923000000000,1792923000000010).unwrap();let a=s.watch(drop(),1792923006000000,1792923006000010).unwrap();assert_eq!(a.reply["p"],"J_CLK_DROP_ACK1");assert_eq!(a.journal["kind"],"watch_clock_discard");let d=s.watch(drop(),1792923006000000,1792923006000010).unwrap();assert_eq!(a.reply,d.reply);s.watch(json!({"p":"J_END1","sid":"watch-session","native_sid":"native-session","count":0,"blocks":0,"start_ms":1792923000000u64,"stop_ms":1792923007000u64,"stop_reason":"user","clock_observations":0,"acquisition":{}}),1792923007000000,1792923007000010).unwrap();assert!(s.complete());}
#[test]fn foreign_echo_cannot_cancel_a_pending_clock(){let mut s=setup();s.watch(req(),1792923000000000,1792923000000010).unwrap();let mut d=drop();d["w1_ms"]=json!(1792923000001u64);assert!(s.watch(d,1792923006000000,1792923006000010).is_err());}
#[test]fn late_original_request_after_cancel_is_idempotent(){let mut s=setup();let a=s.watch(drop(),1792923006000000,1792923006000010).unwrap();let b=s.watch(req(),1792923006000000,1792923006000010).unwrap();assert_eq!(a.reply,b.reply);}
